    teachCards: [TONE_CARD, EVERY_POINT_CARD, PAC_CARD],
    taskBrief: { situation: 'Your class, 5 Kindness, won the inter-class quiz on Monday. Your form teacher, Mrs Lee, stayed back after school to help you practise. Write an email to her.', points: ['Tell her what your class won and when', 'Thank her for helping you prepare', 'Ask politely if the class may celebrate at recess on Friday'], wordCount: 'about 120 words' },
    vocabRevision: ['inform', 'grateful', 'request', 'permission', 'convenient'],
