    supportWords: ['I am pleased to inform you', 'grateful', 'would like to', 'permission', 'Yours sincerely'],
    requiredChecks: [{ id: 'p5-tone-news', label: 'Say what your class won', keywordsAny: ['won', 'quiz', 'first place', 'champion', 'trophy'] }, { id: 'p5-tone-thanks', label: 'Thank Mrs Lee for helping', keywordsAny: ['thank', 'grateful', 'appreciate'] }, { id: 'p5-tone-request', label: 'Ask politely to celebrate', keywordsAny: ['may we', 'could we', 'would like to', 'permission', 'request', 'celebrate', 'celebration'] }],
    rubric: ['All three points covered', 'Polite, semi-formal tone throughout', 'Correct greeting and sign-off'],
    sampleAnswer: 'Dear Mrs Lee,\n\nI am writing on behalf of 5 Kindness to share some good news. I am pleased to inform you that our class won the inter-class quiz on Monday. We beat four other classes and received a trophy, which is now on the shelf in our classroom.\n\nWe are very grateful to you for staying back after school every Wednesday to help us practise. Your tip about reading each question twice made a big difference.\n\nWe would like to request your permission to hold a short celebration during recess on Friday. Please let us know if this is convenient for you.\n\nYours sincerely,\nDaniel Lim\nClass Monitor, 5 Kindness',
